/*
 * Filename: AppineRayTracingShaders.m
 * Project: Appine (App in Emacs)
 * Description: The ray tracing sample's shaders, compiled at runtime from the
 *              source the Makefile embeds (ShaderTypes.h + Shaders.metal).
 */
#import "AppineRayTracingShaders.h"

// Generated by the Makefile: appine_raytracing_shader_source{,_len}.
#include "appine_raytracing_shaders.inc"

id<MTLLibrary> appine_raytracing_shader_library(id<MTLDevice> device) {
    // The sample's Xcode project builds its shaders with
    // MTL_PREPROCESSOR_DEFINITIONS = SUPPORTS_METAL_3=1 and
    // MTL_LANGUAGE_REVISION = Metal30; the Objective-C++ side gets
    // SUPPORTS_METAL_3=1 from the Makefile to match.
    MTLCompileOptions *options = [MTLCompileOptions new];
    options.languageVersion = MTLLanguageVersion3_0;
    options.preprocessorMacros = @{ @"SUPPORTS_METAL_3" : @1 };
    return appine_metal_library_from_source(device, @"raytracing",
                                            appine_raytracing_shader_source,
                                            appine_raytracing_shader_source_len, options);
}
